import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  const root = new Group();

  // 1. PALETTE & DESIGN TOKENS
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const colorSurface = new Color(colors.surface);
  const colorInk = new Color(colors.ink);
  const colorAccent = new Color(colors.accent);

  // 2. CARD GEOMETRY & MATERIAL
  // Aspect ratio 512:320 -> 1.6:1 (Width 2.4, Height 1.5)
  const geom = new PlaneGeometry(2.4, 1.5, 32, 32);

  // Custom Node Material combining the brushed metal texture with an engineered gradient
  const mat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    flatShading: true
  });

  // Load Brushed Metal Texture via Context API
  const imageUrl = config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.wrapS = 1000; // Repeat Wrapping
    tex.wrapT = 1000;

    // TSL setup: Blend texture map with vertical gradient
    const vUv = uv();
    const grad = vUv.y; // simple linear vertical factor
    const baseColorNode = mix(vec3(colorSurface.r, colorSurface.g, colorSurface.b), vec3(colorInk.r, colorInk.g, colorInk.b), grad);

    // Read texture and mix with subtle contrast
    const texColor = texture(tex, vUv.mul(2.0));
    mat.colorNode = mix(baseColorNode, texColor.rgb, 0.45);
    mat.roughnessNode = mix(uniform(0.55), texColor.g, 0.2);
    mat.needsUpdate = true;
  });

  const cardMesh = new Mesh(geom, mat);
  root.add(cardMesh);

  // 3. ACCENT PINSTRIPE (High-end Atelier aesthetic)
  const accentGeom = new PlaneGeometry(0.04, 1.5);
  const accentMat = new MeshStandardNodeMaterial({
    color: colorAccent,
    emissive: colorAccent,
    emissiveIntensity: 0.6,
    roughness: 0.2,
    metalness: 0.8
  });
  const accentBar = new Mesh(accentGeom, accentMat);
  accentBar.position.set(-1.18, 0, 0.005); // Pin to the left edge of the main card
  root.add(accentBar);

  // 4. LOCAL PRODUCT LIGHTING (Ensure brushed metal shines beautifully)
  const localLight = new DirectionalLight(0xffffff, 1.2);
  localLight.position.set(2, 2, 4);
  root.add(localLight);

  // 5. TEXT CONTENT GRAPHICS (Standard Bridge Layout)
  const textGroup = new Group();
  textGroup.position.set(-1.0, 0.5, 0.02); // Top-left indented placement
  root.add(textGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let currentY = 0;

  items.forEach((item) => {
    const isHeader = item.role === 'heading' || item.role === 'title';
    const textNode = ctx.fontAtlas.createText(item.text, {
      fontSize: isHeader ? 0.14 : 0.09,
      color: isHeader ? colors.paper : colors.paper,
      align: 'left',
      maxWidthPx: 450
    });
    textNode.position.y = currentY;
    textGroup.add(textNode);
    currentY -= (isHeader ? 0.18 : 0.13);
  });

  // Apply primitives if specified (Fallback safeties integrated)
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const instance = ctx.primitives[prim.name](root, prim.params);
        if (instance) activePrimitives.push(instance);
      }
    });
  }

  // 6. ENTRANCE ANIMATION (GSAP Weighted Settle)
  root.position.y += 0.3;
  root.scale.set(0.95, 0.95, 0.95);

  const entranceTimeline = gsap.timeline();
  entranceTimeline.to(root.position, {
    y: 0,
    duration: 0.8,
    ease: 'power3.out'
  });
  entranceTimeline.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  // Cleanup handler
  root.userData.cleanup = function() {
    entranceTimeline.kill();
    activePrimitives.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    geom.dispose();
    mat.dispose();
    accentGeom.dispose();
    accentMat.dispose();
  };

  return root;
}
